const pokemonNames: string[] = []

const pokemonsCategorizedReduceCallback: <T extends object = Record<string, string[]>>(total: T, item: IPokemon) => T = (pokemonsCategorized, pokemon) => {
  const newTotal = pokemonsCategorized
  const itemTypeLowerCase = pokemon.type.toLowerCase()
  const itemNameLowerCase = pokemon.name.toLowerCase()
  if (pokemonNames.includes(itemNameLowerCase)) {
    return newTotal
  }
  pokemonNames.push(itemNameLowerCase)
  if (Object.keys(pokemonsCategorized).includes(itemTypeLowerCase)) {
    newTotal[itemTypeLowerCase].push(pokemon.name)
    return newTotal
  }
  newTotal[itemTypeLowerCase] = [pokemon.name]
  return newTotal
}

const pokemonsCategorized = pokemons.reduce<Record<string, string[]>>(pokemonsCategorizedReduceCallback, {})

